package com.collectionlogmaster.tracking;

import com.collectionlogmaster.util.EventBusSubscriber;
import com.collectionlogmaster.util.StringUtils;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class PlayTimeTracker extends EventBusSubscriber {
    private static final int TICKS_PER_MINUTE = 100;

    @Inject
    private Client client;

    @Getter
    private int playTimeTicks = 0;

    @Subscribe
    public void onVarClientIntChanged(VarClientIntChanged e) {
        if (e.getIndex() != VarClientID.ACCOUNT_SUMMARY_PLAYTIME) {
            return;
        }

        int newPlayTimeTicks = client.getVarcIntValue(VarClientID.ACCOUNT_SUMMARY_PLAYTIME) * TICKS_PER_MINUTE;
        int diff = newPlayTimeTicks - playTimeTicks;

        // the VarClient only has minute precision; to avoid overwriting the tick progress we tracked
        // so far, wq only update when the VarClient is ahead or if we drifted more than the maximum
        // expected of 1 minute; there are tricks we could use to be more precise, but I don't think
        // we'll need them; for now, we'll just log and if it becomes a problem we can address it
        // https://github.com/muffyn/time-played/blob/master/src/main/java/com/timeplayed/TimePlayedPlugin.java#L51
        if (newPlayTimeTicks < playTimeTicks && Math.abs(diff) <= TICKS_PER_MINUTE) {
            log.debug("Play time update skipped; current value {}t ({}); rejected diff: {}", playTimeTicks, StringUtils.ticksToDuration(playTimeTicks), diff);
            return;
        }

        if (playTimeTicks != 0 && Math.abs(diff) > TICKS_PER_MINUTE) {
            log.warn("Play time tracking drifted by {}t ({})", diff, StringUtils.ticksToDuration(diff));
        }

        playTimeTicks = newPlayTimeTicks;
        log.debug("Play time set to {}t ({}); diff: {}", playTimeTicks, StringUtils.ticksToDuration(playTimeTicks), diff);
    }

	@Subscribe
	public void onGameTick(GameTick event) {
        playTimeTicks++;
	}
}

package com.collectionlogmaster;

import static com.collectionlogmaster.CollectionLogMasterConfig.CONFIG_GROUP;
import static com.collectionlogmaster.CollectionLogMasterConfig.PLUGIN_VERSION_KEY;

import com.collectionlogmaster.util.EventBusSubscriber;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.externalplugins.PluginHubManifest.DisplayData;

@Slf4j
@Singleton
public class PluginUpdateNotifier extends EventBusSubscriber {
	private static final String[] UPDATE_MESSAGES = {
		"<colHIGHLIGHT>Collection Log Master updated to v" + getPluginVersion(),
		"<colHIGHLIGHT>- Actually fixed issue causing sync to clear all your tasks",
		"<colHIGHLIGHT>- Fixed continuous performance degradation when opening tier task lists",
		"<colHIGHLIGHT>- Fixed some sprites not being loaded correctly",
	};

	@Inject
	ConfigManager configManager;

	@Inject
	ChatMessageManager chatMessageManager;

	public static String getPluginVersion() {
		DisplayData displayData = ExternalPluginManager.getDisplayData(CollectionLogMasterPlugin.class);
		if (displayData != null) {
			return displayData.getVersion();
		}

		// fallback to old ways when running locally
		try (InputStream is = CollectionLogMasterPlugin.class.getResourceAsStream("version")) {
			assert is != null;
			return new String(is.readAllBytes(), StandardCharsets.UTF_8)
					.replace("-SNAPSHOT", "");
		} catch (IOException e) {
			throw new RuntimeException(e);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged) {
		GameState gameState = gameStateChanged.getGameState();
		if (gameState == GameState.LOGGED_IN) {
			checkUpdate();
		}
	}

	private void checkUpdate() {
		boolean isDebug = false;
		String curVersion = getPluginVersion();
		String lastVersion = configManager.getRSProfileConfiguration(CONFIG_GROUP, PLUGIN_VERSION_KEY);

		//noinspection ConstantValue
		if (isDebug || !curVersion.equals(lastVersion)) {
			configManager.setRSProfileConfiguration(CONFIG_GROUP, PLUGIN_VERSION_KEY, curVersion);
			notifyUpdate();
		}
	}

	private void notifyUpdate() {
		//noinspection ConstantConditions
		if (UPDATE_MESSAGES == null || UPDATE_MESSAGES.length == 0) return;

		String replacedMessage = String.join("<br>", UPDATE_MESSAGES);
		chatMessageManager.queue(
				QueuedMessage.builder()
						.type(ChatMessageType.CONSOLE)
						.runeLiteFormattedMessage(replacedMessage)
						.build()
		);
	}
}

