import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import javax.inject.Inject;
import net.runelite.api.Skill;

public class GsonOverride {
	/**
	 * Custom Gson instance capable of parsing additional types.
	 */
	public static Gson GSON;

	@Inject
	public GsonOverride(Gson originalGson) {
		GsonBuilder gsonBuilder = originalGson.newBuilder()
				.enableComplexMapKeySerialization()
				.setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES)
				.registerTypeAdapter(Verification.class, new VerificationAdapter())
				.registerTypeAdapter(VerificationMethod.class, new EnumAdapter<>(VerificationMethod.class))
				.registerTypeAdapter(DiaryRegion.class, new EnumAdapter<>(DiaryRegion.class))
				.registerTypeAdapter(DiaryDifficulty.class, new EnumAdapter<>(DiaryDifficulty.class))
				.registerTypeAdapter(Skill.class, new EnumAdapter<>(Skill.class))
				.registerTypeAdapter(Tag.class, new EnumAdapter<>(Tag.class));

		GSON = gsonBuilder.create();
	}
}

package com.collectionlogmaster.util;

import lombok.NonNull;

import java.time.Duration;

public class StringUtils {
	public static @NonNull String toggleString(@NonNull String curValue, @NonNull String onValue, @NonNull String offValue) {
		return curValue.equals(onValue) ? offValue : onValue;
	}

	public static @NonNull String kebabCase(@NonNull String snakeCase) {
		return snakeCase.toLowerCase().replace('_', '-');
	}

	public static @NonNull String ticksToDuration(int ticks) {
		Duration duration = Duration.ofMillis(ticks * 600L);

		StringBuilder sb = new StringBuilder();

		if (duration.toDays() > 0) {
			sb.append(String.format("%02d:", duration.toDaysPart()));
		}
		if (duration.toHours() > 0) {
			sb.append(String.format("%02d:", duration.toHoursPart()));
		}
		if (duration.toMinutes() > 0) {
			sb.append(String.format("%02d:", duration.toMinutesPart()));
		}

		sb.append(String.format("%02d.%03d", duration.toSecondsPart(), duration.toMillisPart()));

		return sb.toString();
	}
}

package com.collectionlogmaster.util;

import static com.collectionlogmaster.util.GsonOverride.GSON;

import com.collectionlogmaster.PluginUpdateNotifier;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLiteProperties;
import okhttp3.*;

@Slf4j
public class HttpClient {
	private static final MediaType JSON_MEDIA_TYPE = MediaType.parse("application/json; charset=utf-8");

	protected OkHttpClient okHttpClient;

	private final String userAgent;

	@Inject
	public HttpClient(OkHttpClient okHttpClient) {
		this.okHttpClient = okHttpClient;

		String runeliteVersion = RuneLiteProperties.getVersion();
		String pluginVersion = PluginUpdateNotifier.getPluginVersion();
		userAgent = "RuneLite: " + runeliteVersion + ", CLogMaster: " + pluginVersion;
	}

	protected Request.Builder buildRequest(HttpUrl url, Consumer<Request.Builder> methodSetter) {
		Request.Builder builder = new Request.Builder()
				.url(url)
				.header("Content-Type", "application/json")
				.header("User-Agent", userAgent);

		methodSetter.accept(builder);

		return builder;
	}

	protected CompletableFuture<Response> executeRequest(Request request) {
		log.debug("Sending {} request to {}; data = {}", request.method(), request.url(), request.body());

		CompletableFuture<Response> future = new CompletableFuture<>();
		okHttpClient.newCall(request).enqueue(new Callback() {
			@Override
			public void onFailure(@NonNull Call call, @NonNull IOException e) {
				log.error("Async request failed.", e);
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(@NonNull Call call, @NonNull Response response) {
				future.complete(response);
			}
		});
		return future;
	}

	public <T> CompletableFuture<T> get(HttpUrl url, @Nullable Class<T> clazz) {
		Request request = buildRequest(url, Request.Builder::get).build();

		return executeRequest(request)
				.thenApply((response) -> parseResponse(response, clazz));
	}

	public <T> CompletableFuture<T> post(HttpUrl url, @Nullable Class<T> clazz) {
		return post(url, new JsonObject(), clazz);
	}

	public <T> CompletableFuture<T> post(HttpUrl url, Object data, @Nullable Class<T> clazz) {
		RequestBody body = RequestBody.create(JSON_MEDIA_TYPE, GSON.toJson(data));
		Request request = buildRequest(url, builder -> builder.post(body)).build();

		return executeRequest(request)
				.thenApply((response) -> parseResponse(response, clazz));
	}

	public <T> CompletableFuture<T> put(HttpUrl url, Object data, @Nullable Class<T> clazz) {
		RequestBody body = RequestBody.create(JSON_MEDIA_TYPE, GSON.toJson(data));
		Request request = buildRequest(url, builder -> builder.put(body)).build();

		return executeRequest(request)
				.thenApply((response) -> parseResponse(response, clazz));
	}

	public <T> CompletableFuture<T> patch(HttpUrl url, Object data, @Nullable Class<T> clazz) {
		RequestBody body = RequestBody.create(JSON_MEDIA_TYPE, GSON.toJson(data));
		Request request = buildRequest(url, builder -> builder.patch(body)).build();

		return executeRequest(request)
				.thenApply((response) -> parseResponse(response, clazz));
	}

	protected <T> T parseResponse(Response response, @Nullable Class<T> clazz) {
		try (Response res = response) {
			ResponseBody body = res.body();

			if (body == null) {
				throw new RuntimeException("Response body is null");
			}

			String bodyString = body.string();
			if (!response.isSuccessful()) {
				throw new RuntimeException("Response unsuccessful: " + bodyString);
			}

			if (clazz == null) {
				return null;
			}

			return GSON.fromJson(bodyString, clazz);
		} catch (IOException e) {
			log.error("Failed to parse response body.", e);
			throw new RuntimeException("Failed to parse response body", e);
		}
	}
}

package com.collectionlogmaster.util;

import com.google.inject.Inject;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import lombok.Setter;
import lombok.experimental.Accessors;

public class SimpleDebouncer {
	private Future<?> future;

	@Inject
	private ScheduledExecutorService executorService;

	@Setter
	@Accessors(chain = true)
	private int delay = 500;

	public synchronized void debounce(Runnable cb) {
		if (future != null) {
			future.cancel(false);
			future = null;
		}

		future = executorService.schedule(cb, delay, TimeUnit.MILLISECONDS);
	}
}

package com.collectionlogmaster.taskapp;

import com.collectionlogmaster.command.TaskmanCommandManager;
import com.collectionlogmaster.taskapp.domain.CompletedTask;
import com.collectionlogmaster.taskapp.response.UserProfileResponse;
import com.collectionlogmaster.util.EventBusSubscriber;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public class TaskAppStateStorage extends EventBusSubscriber {
	@Inject
	private TaskAppClient taskAppClient;

	@Inject
	private TaskmanCommandManager taskmanCommandManager;

	private volatile TaskAppState state = new TaskAppState();

	@Override
	public void startUp() {
		super.startUp();
		fetch();
	}

	public TaskAppState get() {
		return state;
	}

	public CompletableFuture<Void> fetch() {
		return taskAppClient.getUserProfile()
			.thenAccept(this::updateState)
			.exceptionally(t -> {
				state = new TaskAppState();
				throw new RuntimeException(t.getMessage(), t);
			});
	}

	private void updateState(UserProfileResponse res) {
		Set<String> completedTasks = res.getCompletedTasks().stream()
			.map(CompletedTask::getId)
			.collect(Collectors.toUnmodifiableSet());

		TaskAppState newState = new TaskAppState(
			true,
			res.getActiveTaskId(),
			res.isOfficial(),
			res.isLmsEnabled(),
			res.hasMigrated(),
			completedTasks
		);

		if (state.equals(newState)) {
			return;
		}

		state = newState;
		taskmanCommandManager.updateServer();
	}
}

package com.collectionlogmaster.taskapp.migration;

import static com.collectionlogmaster.CollectionLogMasterConfig.CONFIG_GROUP;
import static com.collectionlogmaster.util.GsonOverride.GSON;

import com.collectionlogmaster.domain.Task;
import com.collectionlogmaster.taskapp.TaskAppClient;
import com.collectionlogmaster.taskapp.TaskAppStateStorage;
import com.collectionlogmaster.taskapp.TaskService;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class MigrationHelper {
	private static final String SAVE_DATA_KEY = "save-data";

	@Inject
	private ConfigManager configManager;

	@Inject
	private TaskService taskService;

	@Inject
	private TaskAppStateStorage taskAppStateStorage;

	@Inject
	private TaskAppClient taskAppClient;

	public boolean canMigrate() {
		SaveData saveData = getOldSaveData();
		Task oldActiveTask = getOldActiveTask();

		return !saveData.isMigrated()
			&& oldActiveTask != null
			&& !isSameActiveTask()
			&& !taskService.isComplete(oldActiveTask.getId())
			&& !taskAppStateStorage.get().hasMigrated();
	}

	public CompletableFuture<Void> migrate() {
		SaveData saveData = getOldSaveData();

		return taskAppClient.migrate(saveData.getActiveTaskId())
			.thenRun(this::markAsMigrated);
	}

	public Task getOldActiveTask() {
		SaveData saveData = getOldSaveData();
		String activeTaskId = saveData.getActiveTaskId();

		return taskService.getTaskById(activeTaskId);
	}

	public SaveData getOldSaveData() {
		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, SAVE_DATA_KEY);
		if (json == null) {
			return new SaveData();
		}

		try {
			return GSON.fromJson(json, SaveData.class);
		} catch (Exception ignored) { }

		return new SaveData();
	}

	public void markAsMigrated() {
		SaveData saveData = getOldSaveData();

		saveData.setMigrated(true);

		String json = GSON.toJson(saveData);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, SAVE_DATA_KEY, json);
	}

	private boolean isSameActiveTask() {
		Task newActiveTask = taskService.getActiveTask();
		Task oldActiveTask = getOldActiveTask();

		return newActiveTask != null
			&& oldActiveTask != null
			&& newActiveTask.getId().equals(oldActiveTask.getId());
	}
}

